#include <iostream>
#include <string>

class Greeter {
public:
    virtual ~Greeter() = default;
    virtual std::string greet(const std::string& name) const = 0;
};

class FormalGreeter : public Greeter {
public:
    std::string greet(const std::string& name) const override {
        return "hello, " + name;
    }
};

class CasualGreeter : public Greeter {
public:
    std::string greet(const std::string& name) const override {
        return "hi, " + name;
    }
};

int main() {
    std::string name;
    std::getline(std::cin, name);
    FormalGreeter formal;
    CasualGreeter casual;
    Greeter& first = formal;
    Greeter& second = casual;
    std::cout << first.greet(name) << std::endl;
    std::cout << second.greet(name) << std::endl;
    return 0;
}

