#include <iostream>
#include <memory>
#include <string>
#include <vector>

class Shape {
public:
    virtual ~Shape() = default;
    virtual long long area() const = 0;
};

class Square : public Shape {
public:
    explicit Square(int side) : side_(side) {}
    long long area() const override { return static_cast<long long>(side_) * side_; }
private:
    int side_;
};

class Circle : public Shape {
public:
    explicit Circle(int radius) : radius_(radius) {}
    long long area() const override { return 3LL * radius_ * radius_; }
private:
    int radius_;
};

int main() {
    std::string line;
    if (!std::getline(std::cin, line)) return 1;
    int n = 0;
    try {
        std::size_t pos = 0;
        n = std::stoi(line, &pos);
        if (pos != line.size()) return 1;
    } catch (...) {
        return 1;
    }
    if (n < 1 || n > 1000) return 1;
    std::vector<std::unique_ptr<Shape>> shapes;
    for (int i = 0; i < n; i++) {
        if (!std::getline(std::cin, line)) return 1;
        std::size_t space = line.find(' ');
        if (space == std::string::npos) return 1;
        std::string kind = line.substr(0, space);
        std::string rest = line.substr(space + 1);
        int parameter = 0;
        try {
            std::size_t pos = 0;
            parameter = std::stoi(rest, &pos);
            if (pos != rest.size()) return 1;
        } catch (...) {
            return 1;
        }
        if (parameter < 0 || parameter > 100) return 1;
        if (kind == "square") {
            shapes.push_back(std::make_unique<Square>(parameter));
        } else if (kind == "circle") {
            shapes.push_back(std::make_unique<Circle>(parameter));
        } else {
            return 1;
        }
    }
    long long total = 0;
    for (const auto& shape : shapes) {
        total += shape->area();
    }
    std::cout << total << std::endl;
    return 0;
}
